#!/usr/bin/env node
/**
 * Reformat every GitHub release body with the current changelog formatting.
 *
 * The release bodies were generated by older toolchain versions and still use
 * flat `### Group` sections instead of the collapsible `<details>` layout (and
 * some include several changelog versions). The canonical, already-reformatted
 * entries live in `CHANGELOG.md`; this script fetches each release and rebuilds
 * its body from those entries, preserving the release's version range, custom
 * intro text, markers and Full Changelog link.
 *
 *   yarn releases:reformat                 # dry run: show what would change
 *   yarn releases:reformat --tag v2.6.0    # one release
 *   yarn releases:reformat --tag v2.6.0 --print
 *   yarn releases:reformat --write         # update every release
 *
 * `--include-drafts` also updates draft releases. The script is idempotent: a
 * release whose body already matches is left untouched.
 */

import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { normalizeReleaseVersion, reformatChangelogContent } from '@deltabox/toolchain/changelog';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const CHANGELOG = path.join(ROOT, 'CHANGELOG.md');

interface ReleaseInfo {
    tagName: string;
    isDraft: boolean;
    isPrerelease: boolean;
    publishedAt: string;
}

interface RawEntry {
    version: string;
    text: string;
}

interface Options {
    write: boolean;
    print: boolean;
    includeDrafts: boolean;
    tag?: string;
    repo: string;
}

/** `owner/name` from the repository URL (or `--repo`). */
function defaultRepo(): string {
    const pkg = JSON.parse(fs.readFileSync(path.join(ROOT, 'package.json'), 'utf8')) as {
        repository?: string | { url?: string };
    };
    const url = typeof pkg.repository === 'string' ? pkg.repository : (pkg.repository?.url ?? '');
    const match = /github\.com[/:]([^/]+)\/(.+?)(?:\.git)?$/.exec(url);
    return match ? `${match[1]}/${match[2]}` : 'deltabox-studio/toolchain';
}

function usage(): never {
    console.error(
        [
            'Usage: yarn releases:reformat [--write] [--tag <tag>] [--print] [--include-drafts] [--repo <owner/name>]',
            '',
            '  --write           Update the releases with `gh release edit`.',
            '  --tag <tag>       Only process one release tag.',
            '  --print           Print the proposed body for each changed release.',
            '  --include-drafts  Include draft releases.',
            '  --repo <slug>     GitHub repository (default: package.json repository).',
        ].join('\n')
    );
    process.exit(1);
}

function parseArgs(argv: string[]): Options {
    const options: Options = {
        write: false,
        print: false,
        includeDrafts: false,
        repo: defaultRepo(),
    };
    for (let index = 0; index < argv.length; index++) {
        const arg = argv[index];
        if (arg === '--write') options.write = true;
        else if (arg === '--print') options.print = true;
        else if (arg === '--include-drafts') options.includeDrafts = true;
        else if (arg === '--tag') {
            options.tag = argv[++index];
            if (!options.tag) usage();
        } else if (arg === '--repo') {
            options.repo = argv[++index] ?? '';
            if (!options.repo) usage();
        } else if (arg === '--help' || arg === '-H') usage();
        else usage();
    }
    return options;
}

function gh(args: string[]): string {
    return execFileSync('gh', args, { encoding: 'utf8' });
}

/** Split a changelog (or release body) into raw `## x.y.z` entries. */
function splitEntries(content: string): RawEntry[] {
    const heading = /^##\s+(\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?)(?:\s|$)/gm;
    const matches = [...content.matchAll(heading)];
    return matches.map((match, index) => ({
        version: match[1]!,
        text: content.slice(match.index, matches[index + 1]?.index ?? content.length).trim(),
    }));
}

/** `version -> raw entry` for every version in the local changelog. */
function localEntries(): Map<string, string> {
    return new Map(
        splitEntries(fs.readFileSync(CHANGELOG, 'utf8').replace(/^\uFEFF/, '')).map(entry => [
            entry.version,
            entry.text,
        ])
    );
}

function stripMarkers(entry: string): string {
    return entry
        .split('\n')
        .filter(line => !/^<!--\s*release:(?:start|end)\s*-->$/.test(line.trim()))
        .join('\n')
        .trim();
}

/** Repair a legacy nested bullet that was double-prefixed (`  - - text`). */
function cleanLocalEntry(entry: string): string {
    return stripMarkers(entry).replace(/^(\s*)- - /gm, '$1- ');
}

function addMarkers(entry: string): string {
    const lines = entry.split('\n');
    const heading = lines.findIndex(line => line.startsWith('## '));
    if (heading < 0) return entry;
    let insertAt = heading + 1;
    if (lines[insertAt]?.trim() === '') insertAt += 1;
    lines.splice(insertAt, 0, '<!-- release:start -->', '');
    lines.push('', '<!-- release:end -->');
    return lines.join('\n');
}

/**
 * Extract release-specific prose before the first real changelog section (eg.
 * the `### Migration from v1` note on 2.1.1). A `###` heading belongs to the
 * intro when no commit bullet follows it before the next heading.
 */
function extractIntro(entry: string): string {
    const lines = stripMarkers(entry).split('\n');
    const heading = lines.findIndex(line => line.startsWith('## '));
    if (heading < 0) return '';
    const start = heading + 1;

    const startsBody = (index: number): boolean => {
        const line = lines[index]?.trim() ?? '';
        if (!line) return false;
        if (line.startsWith('- ')) return true;
        if (line.startsWith('<details')) return true;
        if (/^####\s+/.test(line)) return true;
        if (!/^###\s+/.test(line) || /^###\s+Package changes\s*$/.test(line)) return false;
        for (let next = index + 1; next < lines.length; next++) {
            const candidate = lines[next]?.trim() ?? '';
            if (/^###\s+/.test(candidate)) return false;
            if (candidate.startsWith('<details')) return false;
            if (candidate.startsWith('- ')) return true;
        }
        return false;
    };

    let bodyStart = lines.length;
    for (let index = start; index < lines.length; index++) {
        if (startsBody(index)) {
            bodyStart = index;
            break;
        }
    }
    return lines.slice(start, bodyStart).join('\n').trim();
}

/** Preserve text after the release marker (the Full Changelog link, notes). */
function extractTail(entry: string): string {
    const lines = entry.split('\n');
    const end = lines.findIndex(line => /<!--\s*release:end\s*-->/.test(line));
    if (end >= 0) {
        const tail = lines
            .slice(end + 1)
            .filter(line => !/^<!--\s*release:(?:start|end)\s*-->$/.test(line.trim()))
            .join('\n')
            .trim();
        if (tail) return tail;
    }
    return /\*\*Full Changelog\*\*:.*$/m.exec(entry)?.[0] ?? '';
}

/** Insert release-specific intro prose after the version heading. */
function injectIntro(entry: string, intro: string): string {
    if (!intro.trim() || entry.includes(intro.trim())) return entry;
    const lines = entry.split('\n');
    const heading = lines.findIndex(line => line.startsWith('## '));
    if (heading < 0) return entry;
    let insertAt = heading + 1;
    if (lines[insertAt]?.trim() === '') insertAt += 1;
    lines.splice(insertAt, 0, intro.trim(), '');
    return lines.join('\n');
}

/**
 * Rebuild one release body from the local changelog entries. The old body's
 * version list is preserved (some releases intentionally included multiple
 * changelog versions), along with its custom intro text and Full Changelog link.
 */
function newBody(
    body: string,
    entries: Map<string, string>,
    repo: string,
    tag: string,
    publishedAt: string
): { body: string; reformatted: boolean } {
    const version = normalizeReleaseVersion(tag);
    const oldEntries = splitEntries(body);
    if (oldEntries.length === 0) {
        if (!version) return { body, reformatted: false };
        const local = entries.get(version);
        const synthetic = `## ${version}\n\n${body}`;
        const hasMarkers = /<!--\s*release:start\s*-->/.test(body);
        if (local) {
            let entry = cleanLocalEntry(local);
            if (!extractIntro(entry)) entry = injectIntro(entry, extractIntro(synthetic));
            if (hasMarkers) entry = addMarkers(entry);
            const tail = extractTail(body);
            return {
                body: [entry, tail].filter(Boolean).join('\n\n'),
                reformatted: true,
            };
        }
        const date = publishedAt
            ? new Intl.DateTimeFormat('en-US', { month: 'long', year: 'numeric' }).format(
                  new Date(publishedAt)
              )
            : '';
        const heading = `## ${version}${date ? ` (${date})` : ''}`;
        return {
            body: reformatChangelogContent(`${heading}\n\n${body}`, repo, false, false).trimEnd(),
            reformatted: true,
        };
    }

    const hasMarkers = /<!--\s*release:start\s*-->/.test(body);
    const composed = oldEntries.map((old, index) => {
        const local = entries.get(old.version);
        let entry: string;
        if (local) {
            entry = cleanLocalEntry(local);
            if (!extractIntro(entry)) entry = injectIntro(entry, extractIntro(old.text));
            if (hasMarkers && index === 0) entry = addMarkers(entry);
        } else {
            // A release body from before the local changelog existed: use the
            // programmatic reformatter as the fallback.
            entry = reformatChangelogContent(old.text, repo, hasMarkers && index === 0, false)
                .replace(/^# Changelog\n\n/, '')
                .trimEnd();
        }
        const tail = extractTail(old.text);
        return [entry, tail].filter(Boolean).join('\n\n');
    });

    return { body: composed.join('\n\n'), reformatted: true };
}

function normalize(body: string): string {
    return body.replace(/\r\n/g, '\n').replace(/\s+$/g, '');
}

function main(): void {
    const options = parseArgs(process.argv.slice(2));
    const entries = localEntries();
    const releases = JSON.parse(
        gh([
            'release',
            'list',
            '-R',
            options.repo,
            '--limit',
            '1000',
            '--json',
            'tagName,isDraft,isPrerelease,publishedAt',
        ])
    ) as ReleaseInfo[];

    const selected = releases.filter(release => {
        if (options.tag) return release.tagName === options.tag;
        return options.includeDrafts || !release.isDraft;
    });
    if (selected.length === 0) {
        console.error(options.tag ? `No release found for ${options.tag}.` : 'No releases found.');
        process.exitCode = 1;
        return;
    }

    const temp = fs.mkdtempSync(path.join(os.tmpdir(), 'dbx-release-notes-'));
    let changed = 0;
    try {
        for (const release of selected) {
            const body = gh([
                'release',
                'view',
                release.tagName,
                '-R',
                options.repo,
                '--json',
                'body',
                '--jq',
                '.body',
            ]);
            const next = newBody(body, entries, options.repo, release.tagName, release.publishedAt);
            if (!next.reformatted || normalize(next.body) === normalize(body)) {
                console.log(`= ${release.tagName} (unchanged)`);
                continue;
            }
            changed += 1;
            console.log(`~ ${release.tagName} (${body.length} -> ${next.body.length} bytes)`);
            if (options.print) console.log(`\n${next.body}\n`);
            if (options.write) {
                const file = path.join(temp, `${release.tagName.replace(/[\\/]/g, '_')}.md`);
                fs.writeFileSync(file, `${next.body}\n`, 'utf8');
                gh(['release', 'edit', release.tagName, '-R', options.repo, '--notes-file', file]);
                console.log('  updated');
            }
        }
    } finally {
        fs.rmSync(temp, { recursive: true, force: true });
    }

    console.log(
        options.write
            ? `Updated ${changed} release(s).`
            : `Dry run: ${changed} release(s) would be updated. Re-run with --write to apply.`
    );
}

main();
